{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C23"],
      "claim": "Zeaxanthin, a highly lipophilic polyene, shows high oral bioavailability only when ingested with fat (egg yolk), illustrating that lipophilic polyene scaffolds require lipid-based delivery to achieve high systemic exposure; this condition-dependent behavior is more analogous to fenretinide than the small hydrophilic drugs in other records.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Meperidine/pethidine has an absolute oral bioavailability of about 50–60%, but its small, basic, non-lipophilic structure is not transferable to fenretinide and does not provide affirmative evidence for high fenretinide bioavailability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C10"],
      "claim": "Teriflunomide has near-complete oral bioavailability, but it is a small, relatively polar anilide; the long conjugated lipophilic retinoid chain of fenretinide is not represented by this record, so the high value does not transfer.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is fenretinide (4-HPR), a highly lipophilic, poorly water-soluble retinoid with recognized low and variable oral bioavailability. The provided high-bioavailability records come from structurally dissimilar small molecules or from lipophilic carotenoids only under fat-assisted conditions, so they do not override the query-specific low-bioavailability behavior. Prediction: low (F < 20%).",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for fenretinide is provided in the evidence set.",
    "No human intravenous comparator study for fenretinide is available to establish an absolute F value.",
    "The effect of food or lipid-based formulation on fenretinide bioavailability is not directly quantified in the records."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "moderate",
      "card_ids": ["C23"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "lipophilic polyene/carotenoid"
    },
    {
      "applicability": "low",
      "card_ids": ["C08"],
      "decision_effect": "no_change",
      "direction": "contradictory",
      "family": "small basic opioid analgesic"
    },
    {
      "applicability": "low",
      "card_ids": ["C10"],
      "decision_effect": "no_change",
      "direction": "contradictory",
      "family": "small anilide antimetabolite"
    }
  ],
  "revision_action": "initial"
}

